   336→                <div className="border-2 border-neo-border bg-neo-surface shadow-[6px_6px_0px_0px_var(--neo-shadow)] overflow-hidden">
   337→                  <div className="px-4 py-3 border-b-2 border-neo-border bg-neo-text text-neo-text-inverse flex items-center justify-between">
   338→                    <span className="font-mono text-[10px] uppercase tracking-[0.22em] text-white/70">
   339→                      {tPlayer("tracklist.title")}
   340→                    </span>
   341→                    <span className="font-mono text-[10px] uppercase tracking-[0.22em] text-white/50">
   342→                      {queue.length}
   343→                    </span>
