   346→                    tracks={queue}
   347→                    currentTrackId={track?.id ?? null}
   348→                    currentIndex={currentIndex}
   349→                    isPlaying={isPlaying}
   350→                    isLoading={mediaAllowed && status === "loading"}
   351→                    disabled={isPlayerUnavailable}
